    ppms_credit: float | None = None
    ppms_updated_at: str | None = None
    ami_hourly: tuple[PeriodReading, ...] = ()
    ami_daily: tuple[PeriodReading, ...] = ()
    # An AMI read failed and no earlier answer of that feed could stand in, so
    # the AMI series above is missing what that feed holds. The sensors show
    # what there is; the statistics import waits for a poll that read it.
    ami_read_failed: bool = False
    bills: tuple[BillInfo, ...] = ()
    amount_due: PayableInfo | None = None
    meter_registers: tuple[MeterRegister, ...] = ()
    green_goals: tuple[GreenGoal, ...] = ()
    greenup: GreenUpInfo | None = None
    ev_wallet: EvWalletInfo | None = None
    ev_session: EvSessionInfo | None = None
    ev_last_charge: EvChargeInfo | None = None
    ev_unpaid: EvUnpaidInfo | None = None
    unread_notifications: int | None = None
    bill_delivery: BillDeliveryInfo | None = None
    fcus: tuple[FcuInfo, ...] = ()
    tariff: TariffInfo | None = None

    @property
    def premise_id(self) -> str:
        return self.premise.id

    @property
    def last_bill(self) -> BillInfo | None:
        return self.bills[-1] if self.bills else None

    @property
    def electricity_kwh(self) -> float:
        return self.electricity.total if self.electricity else 0.0

    @property
    def water_m3(self) -> float:
        return self.water.total if self.water else 0.0

    @property
    def electricity_periods(self) -> tuple[PeriodReading, ...]:
        return self.electricity.periods if self.electricity else ()

    @property
    def water_periods(self) -> tuple[PeriodReading, ...]:
        return self.water.periods if self.water else ()

    @property
    def gas_periods(self) -> tuple[PeriodReading, ...]:
        return self.gas.periods if self.gas else ()

    def meter(self, utility: str) -> MeterRegister | None:
        wanted = fold_text(utility)
        for item in self.meter_registers:
            if fold_text(item.utility) == wanted:
                return item
        return None

    def goal(self, kind: str) -> GreenGoal | None:
        wanted = fold_text(kind)
        for item in self.green_goals:
            if fold_text(item.kind) == wanted:
                return item
        return None

"""What the config entry keeps: the session, and nothing that reopens the account."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

from custom_components.sp_group import _forget_password
from custom_components.sp_group.client import Session, session_entry_data
from custom_components.sp_group.const import (
    CONF_ACCESS_TOKEN,
    CONF_ID_TOKEN,
    CONF_PASSWORD,
    CONF_REFRESH_TOKEN,
    CONF_USERNAME,
)


def test_entry_data_carries_the_session_and_not_the_password() -> None:
    """The password buys one token exchange; the refresh token buys the rest.

    Everything in the entry lands in ``.storage`` and in every Home Assistant
    backup, so a field nothing reads back does not belong there.
    """
    session = Session(access_token="access", id_token="ident", refresh_token="refresh")

    data = session_entry_data(session, "user@example.com")

    assert data == {
        CONF_USERNAME: "user@example.com",
        CONF_ACCESS_TOKEN: "access",
        CONF_ID_TOKEN: "ident",
        CONF_REFRESH_TOKEN: "refresh",
    }
    assert CONF_PASSWORD not in data


@dataclass
class _Entry:
    data: dict[str, Any] = field(default_factory=dict)


@dataclass
class _ConfigEntries:
    entry: _Entry
    written: list[dict[str, Any]] = field(default_factory=list)

    def async_update_entry(self, entry: _Entry, *, data: dict[str, Any]) -> None:
        entry.data = data
        self.written.append(data)


@dataclass
class _Hass:
    config_entries: _ConfigEntries


def test_a_password_an_earlier_version_stored_is_dropped_on_load() -> None:
    entry = _Entry(
        {
            CONF_USERNAME: "user@example.com",
            CONF_PASSWORD: "secret",
            CONF_ACCESS_TOKEN: "access",
            CONF_ID_TOKEN: "ident",
            CONF_REFRESH_TOKEN: "refresh",
        }
    )
    hass = _Hass(_ConfigEntries(entry))

    _forget_password(hass, entry)

    assert entry.data == {
        CONF_USERNAME: "user@example.com",
        CONF_ACCESS_TOKEN: "access",
        CONF_ID_TOKEN: "ident",
        CONF_REFRESH_TOKEN: "refresh",
    }


def test_an_entry_without_a_password_is_left_alone() -> None:
    entry = _Entry({CONF_USERNAME: "user@example.com", CONF_ACCESS_TOKEN: "access"})
    hass = _Hass(_ConfigEntries(entry))

    _forget_password(hass, entry)

    assert hass.config_entries.written == []

"""The pure modules import no Home Assistant code and only lower layers."""

from __future__ import annotations

import ast
from pathlib import Path

import pytest

PACKAGE = Path(__file__).resolve().parent.parent / "custom_components" / "sp_group"

# Each module may import only the siblings listed for it.
ALLOWED_SIBLINGS = {
    "const": set(),
    "models": {"const"},
    "history": {"const", "models"},
    "mapper": {"const", "models", "history"},
    "client": {"const", "models"},
}


def _sibling_imports(module: str) -> set[str]:
    tree = ast.parse((PACKAGE / f"{module}.py").read_text())
    names = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom) and node.level == 1 and node.module:
            names.add(node.module)
        elif isinstance(node, ast.ImportFrom) and node.module:
            names.add(node.module.split(".")[0])
        elif isinstance(node, ast.Import):
            names.update(alias.name.split(".")[0] for alias in node.names)
    return names


@pytest.mark.parametrize("module", sorted(ALLOWED_SIBLINGS))
def test_no_homeassistant_import(module: str) -> None:
    assert "homeassistant" not in _sibling_imports(module)


@pytest.mark.parametrize("module", sorted(ALLOWED_SIBLINGS))
def test_only_lower_layers_imported(module: str) -> None:
    package_modules = {path.stem for path in PACKAGE.glob("*.py")}
    imported = _sibling_imports(module) & package_modules
    assert imported <= ALLOWED_SIBLINGS[module]

