# The instant every test run pretends it is: a day inside the recorded AMI
# window in jarvis_ami_day.json. AMI windows, "today" buckets, and token expiry
# are all derived from it, so a run is reproducible whatever the wall clock
# says when it starts.
FIXED_NOW = datetime(2026, 8, 2, 12, 0, tzinfo=SG_TZ)


@dataclass
class FixedClock:
    """A ``Clock`` the test moves by hand instead of the system clock."""

    instant: datetime = FIXED_NOW
    elapsed: float = 0.0

    def now(self) -> datetime:
        return self.instant.astimezone(SG_TZ)

    def timestamp(self) -> int:
        return int(self.instant.timestamp())

    def monotonic(self) -> float:
        return self.elapsed


def load_fixture(name: str) -> bytes:
    return (FIXTURES / name).read_bytes()


def fixture_client(
    transport: FixtureTransport | None = None, clock: FixedClock | None = None
) -> SpGroupClient:
    client = SpGroupClient(
        transport=transport or FixtureTransport(), clock=clock or FixedClock()
    )
    client.login("user@example.com", "secret")
    return client


@dataclass
class RecordedRequest:
    method: str
    url: str
    headers: dict[str, str]
    body: bytes | None
    timeout: int | None = None


@dataclass
class FixtureTransport:
    """Serves recorded Auth0/Jarvis JSON. Does not implement client logic."""

    fail_login: bool = False
    require_mfa: bool = False
    mfa_success: bool = False
    mfa_oob: bool = False
    mfa_challenge_binding: str = "prompt"
    authenticators_bare: bool = False
    charts_fixture: str = "jarvis_charts.json"
    # Exact responses to force for one path, checked before normal routing.
    responses: dict[str, HttpResponse] = field(default_factory=dict)
    requests: list[RecordedRequest] = field(default_factory=list)

    def request(
        self,
        method: str,
        url: str,
        headers: Mapping[str, str],
        body: bytes | None,
        *,
        timeout: int | None = None,
    ) -> HttpResponse:
        self.requests.append(
            RecordedRequest(
                method=method,
                url=url,
                headers=dict(headers),
                body=body,
                timeout=timeout,
            )
        )
        parsed = urlparse(url)
        origin = f"{parsed.scheme}://{parsed.netloc}"
        path = parsed.path
        if path in self.responses:
            return self.responses[path]
        if method == "POST" and origin == IDENTITY_HOST and path == OAUTH_TOKEN_PATH:
            request_body = json.loads(body.decode("utf-8")) if body else {}
            if (self.require_mfa or self.mfa_oob) and request_body.get(
                "grant_type"
            ) == AUTH0_GRANT_TYPE:
                return HttpResponse(
                    status=403,
                    body=load_fixture("oauth_token_mfa_required.json"),
                )
            if self.mfa_success and request_body.get("grant_type") in {
                AUTH0_MFA_OOB_GRANT,
                AUTH0_MFA_OTP_GRANT,
            }:
                return HttpResponse(
                    status=200,
                    body=load_fixture("oauth_token_mfa_success.json"),
                )
            if self.fail_login:
                return HttpResponse(
                    status=403,
                    body=load_fixture("oauth_token_invalid_grant.json"),
                )
            return HttpResponse(
                status=200,
                body=load_fixture("oauth_token_success.json"),
            )
        if (
            method == "GET"
            and origin == AUTH0_MFA_OAUTH_HOST
            and path == AUTH0_MFA_AUTHENTICATORS_PATH
        ):
            fixture = (
                "oauth_token_mfa_authenticators_bare.json"
                if self.authenticators_bare
                else "oauth_token_mfa_authenticators_sms.json"
            )
            return HttpResponse(status=200, body=load_fixture(fixture))
        if (
            method == "POST"
            and origin == AUTH0_MFA_OAUTH_HOST
            and path == AUTH0_MFA_CHALLENGE_PATH
        ):
            challenge = {
                "challenge_type": "oob",
                "oob_code": "oob-code",
                "binding_method": self.mfa_challenge_binding,
            }
            return HttpResponse(
                status=200,
                body=json.dumps(challenge).encode("utf-8"),
            )
        if method == "GET" and origin == B2C_HOST and path == JARVIS_ME_PATH:
            return HttpResponse(
                status=200,
                body=load_fixture("jarvis_me.json"),
            )
        if (
            method == "GET"
            and origin == B2C_HOST
            and path.startswith(f"{JARVIS_CHARTS_PATH}/")
        ):
            return HttpResponse(
                status=200,
                body=load_fixture(self.charts_fixture),
            )
        if (
            method == "GET"
            and origin == B2C_HOST
            and path.startswith(f"{JARVIS_SMRD_PATH}/")
        ):
            return HttpResponse(
                status=200,
                body=load_fixture("jarvis_smrd.json"),
            )
        if method == "POST" and origin == B2C_HOST and path == JARVIS_AMI_PATH:
            grouped = "day"
            if body:
                payload = json.loads(body.decode("utf-8"))
                grouped = str(payload.get("grouped_by") or "day")
            name = (
                "jarvis_ami_month.json" if grouped == "month" else "jarvis_ami_day.json"
            )
            return HttpResponse(
                status=200,
                body=load_fixture(name),
            )
        if (
            method == "GET"
            and origin == B2C_HOST
            and path.startswith(f"{JARVIS_PPMS_PATH}/")
        ):
            return HttpResponse(
                status=401,
                body=b'{"error":"no_ppms_account"}',
            )
        if method == "GET" and origin == B2C_HOST and path == JARVIS_GREEN_GOALS_PATH:
            return HttpResponse(
                status=200,
                body=load_fixture("jarvis_greengoals.json"),
            )
        if method == "GET" and origin == B2C_HOST and path == NJORD_PAYABLES_PATH:
            return HttpResponse(
                status=200,
                body=load_fixture("njord_payables.json"),
            )
        if method == "GET" and origin == B2C_HOST and path == NJORD_HISTORY_PATH:
            return HttpResponse(
                status=200,
                body=load_fixture("njord_history.json"),
            )
        return HttpResponse(status=404, body=b"{}")


def billed_totals_from_charts_payload(
    payload: dict[str, object],
) -> tuple[float, float]:
    """Read consumption.current from the fixture JSON (field names from the APK)."""

    def _sum(section_key: str) -> float:
        section = payload[section_key]
        assert isinstance(section, dict)
        data = section["data"]
        assert isinstance(data, list)
        total = 0.0
        for row in data:
            assert isinstance(row, dict)
            consumption = row["consumption"]
            assert isinstance(consumption, dict)
            total += float(consumption["current"])
        return total

    return _sum("elec"), _sum("water")

"""The shipped catalog names every sensor and every state the mapper emits."""

from __future__ import annotations

import ast
import json
import re
from pathlib import Path

import pytest

from custom_components.sp_group import const

PACKAGE = Path(__file__).resolve().parent.parent / "custom_components" / "sp_group"
STRINGS = json.loads((PACKAGE / "strings.json").read_text(encoding="utf-8"))
SENSORS = STRINGS["entity"]["sensor"]
# hassfest rejects anything else as a translation key.
TRANSLATION_KEY = re.compile(r"^[a-z0-9_]+$")


def _sensor_keys() -> set[str]:
    return {
        value for name, value in vars(const).items() if name.startswith("SENSOR_KEY_")
    }


def _sensor_states() -> set[str]:
    return {
        value for name, value in vars(const).items() if name.startswith("SENSOR_STATE_")
    }


def _sensor_units() -> set[str]:
    return {value for name, value in vars(const).items() if name.startswith("UNIT_")}


def _declared(prefix: str) -> set[str]:
    return {name for name in vars(const) if name.startswith(prefix)}


# The mapper builds a spec either directly or through its _spec helper, which
# takes the value positionally and names the unit argument ``unit``.
_SPEC_FACTORIES = {"SensorSpec": "native_value", "_spec": "unit_of_measurement"}


def _spec_calls(tree: ast.AST) -> list[ast.Call]:
    """Every spec construction in the mapper, read from the AST.

    Walking the AST keeps the check off comments and string content, and
    covers every call site, including ones a grep for a single literal misses.
    """
    return [
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id in _SPEC_FACTORIES
    ]


def _field_literals(call: ast.Call, field: str) -> list[ast.expr]:
    """The arguments a spec call passes for one ``SensorSpec`` field."""
    assert isinstance(call.func, ast.Name)
    if call.func.id == "_spec":
        if field == "native_value" and len(call.args) > 1:
            return [call.args[1]]
        if field == "unit_of_measurement":
            return [kw.value for kw in call.keywords if kw.arg == "unit"]
        return []
    return [kw.value for kw in call.keywords if kw.arg == field]


def _field_exprs(calls: list[ast.Call], field: str) -> list[ast.expr]:
    """Every expression a spec call passes for one ``SensorSpec`` field."""
    return [expr for call in calls for expr in _field_literals(call, field)]


def _string_constants(exprs: list[ast.expr]) -> list[str]:
    """String constants anywhere inside, so an IfExp arm counts as a literal."""
    return [
        node.value
        for expr in exprs
        for node in ast.walk(expr)
        if isinstance(node, ast.Constant) and isinstance(node.value, str)
    ]


def _named(exprs: list[ast.expr], prefix: str) -> set[str]:
    return {
        node.id
        for expr in exprs
        for node in ast.walk(expr)
        if isinstance(node, ast.Name) and node.id.startswith(prefix)
    }


MAPPER = ast.parse((PACKAGE / "mapper.py").read_text(encoding="utf-8"))
SPEC_CALLS = _spec_calls(MAPPER)


def test_the_mapper_walk_covers_every_spec_construction() -> None:
    """Guard the guard: an empty walk would pass the literal checks vacuously."""
    assert len(SPEC_CALLS) >= 10


def test_every_spec_state_is_a_constant_never_a_literal() -> None:
    """A state written as a literal ships untranslated, so it needs a constant."""
    states = _field_exprs(SPEC_CALLS, "native_value")
    assert states, "no state expression found; the literal check is vacuous"
    assert _string_constants(states) == []
